// Custom container (e.g., uses std::deque internally)
template <typename T>
class MyVec : public std::vector<T> {};

// Custom comparator for min-heap behavior
struct MinCompare {
    template <typename T>
    bool operator()(const T& a, const T& b) const { return a > b; }
};

// Customized priority_queue definition
// Underlying container: MyVec<int>
// Comparison type: MinCompare
std::priority_queue<
    int,
    MyVec<int>,
    MinCompare
> min_heap;

// Example with std::list for non-random access
std::priority_queue<
    float,
    std::list<float>
> list_pq; // ERROR: std::list lacks random access required by default heap algorithm

std::priority_queue<
    float,
    std::vector<float> // Default
> default_pq;
